<?php
declare(strict_types=1);
session_start(); require dirname(__DIR__).'/config/config.php'; require_sign_in();
$role=$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$canAdd=in_array($role,['director','admin','sub_admin'],true);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$canAdd){http_response_code(403);exit('You cannot add schools.');}$name=trim((string)($_POST['name']??''));$location=trim((string)($_POST['location']??''));$directorId=$role==='director'?$uid:(int)($_POST['director_id']??0);if($name===''||strlen($name)>180){$error='Enter a school name (up to 180 characters).';}elseif($role!=='director'&&!$directorId){$error='Choose the director who owns this school.';}else{try{$pdo=db();$pdo->beginTransaction();if($role!=='director'){$d=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='director' AND status='active'");$d->execute([$directorId]);if(!$d->fetch())throw new DomainException('Choose an active director account.');}$q=$pdo->prepare('INSERT INTO schools (name,location,status,created_by) VALUES (?,?,\'active\',?)');$q->execute([$name,$location?:null,$uid]);$schoolId=(int)$pdo->lastInsertId();$m=$pdo->prepare("INSERT INTO school_memberships (school_id,user_id,scope) VALUES (?,?,'manager')");$m->execute([$schoolId,$directorId]);if($role!=='director'){$m->execute([$schoolId,$uid]);}$a=$pdo->prepare('INSERT INTO audit_logs (actor_id,action,entity_type,entity_id,details) VALUES (?,?,?,?,?)');$a->execute([$uid,'create','school',$schoolId,json_encode(['name'=>$name,'director_id'=>$directorId])]);$pdo->commit();header('Location: schools.php?saved=1');exit;}catch(DomainException $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='School could not be saved. Verify database/schema.sql is up to date.';}}}
$schools=[];$directors=[];$loadError='';try{$pdo=db();if($canAdd&&$role!=='director')$directors=$pdo->query("SELECT id,name,email FROM users WHERE role='director' AND status='active' ORDER BY name")->fetchAll();if(in_array($role,['system_admin','sub_admin'],true))$schools=$pdo->query('SELECT s.*,u.name director FROM schools s LEFT JOIN school_memberships m ON m.school_id=s.id AND m.scope=\'manager\' LEFT JOIN users u ON u.id=m.user_id ORDER BY s.created_at DESC')->fetchAll();else{$q=$pdo->prepare('SELECT s.*,u.name director FROM schools s JOIN school_memberships m ON m.school_id=s.id LEFT JOIN users u ON u.id=m.user_id WHERE m.user_id=? ORDER BY s.created_at DESC');$q->execute([$uid]);$schools=$q->fetchAll();}}catch(Throwable $ex){$loadError='Schools are not available. Apply the latest database schema.';}
$saved=isset($_GET['saved']);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schools · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item active" href="schools.php" aria-current="page">▦ &nbsp;Schools</a><a class="nav-item" href="people.php">♧ &nbsp;People</a><a class="nav-item" href="notes.php">▤ &nbsp;Learning notes</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Schools</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name'])?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">SCHOOL NETWORK</div><h1>Schools</h1><p class="muted">Manage school records within your access.</p></div></section><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><?php if($saved):?><div class="notice success" role="status">School added and linked to its director.</div><?php endif;?><?php if($loadError):?><div class="notice error" role="alert"><?=e($loadError)?></div><?php endif;?><?php if($canAdd):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">REGISTER</div><h2>Add a school</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label for="school-name">School name</label><input id="school-name" name="name" maxlength="180" required></div><div><label for="location">Location</label><input id="location" name="location" maxlength="180"></div><?php if($role!=='director'):?><div><label for="director">School director</label><select id="director" name="director_id" required><option value="">Choose director</option><?php foreach($directors as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?> · <?=e($d['email'])?></option><?php endforeach;?></select></div><?php endif;?></div><button class="button primary" type="submit">Save school</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">REGISTERED</div><h2>School records</h2></div><span class="count-pill"><?=count($schools)?> schools</span></div><?php if(!$schools):?><div class="empty-state"><span class="empty-icon">▦</span><h3>No schools in your access yet</h3><p>School records appear when a director registers a school or shares access with you.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>School</th><th>Location</th><th>Director</th><th>Status</th></tr></thead><tbody><?php foreach($schools as $s):?><tr><td class="school-cell"><?=e($s['name'])?></td><td><?=e($s['location']?:'—')?></td><td><?=e($s['director']?:'—')?></td><td><?=e(ucfirst($s['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main></div></body></html>
